import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public {
        c = new C();
    }

    function testFuzz_property(uint256 initialSum, uint256 newSum, address actor) public {
        vm.assume(actor != address(0));
        vm.prank(actor);
        c.SetMinSum(initialSum);
