// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address logAddr) public {
        vm.assume(logAddr != address(0));
        c.SetLogFile(logAddr);
        assertTrue(address(c.Log()) == logAddr);
    }
}

contract InvMutTest
{
    C c;

    constructor(C _c) { c = _c; }

    function test(uint _val, uint _amount) public
    {
        require(_val > 0);
        c.SetLogFile(address(this));
        c.SetMinSum(_val);
        c.Deposit{value: _amount + 1}();
        c.Collect(_amount + 1);
        assert(c.balances(address(this)) == 0);
    }

    receive() external payable {}
    fallback() external payable {}
}

contract InvMutTest
{
    C c;

    constructor(C _c) { c = _c; }

    function test(uint _val) public
    {
        require(_val != 0);
        c.SetMinSum(_val);
        assert(c.MinSum() == _val);
    }

    receive() external payable {}
    fallback() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint val) public payable {
        require(val < 2**256 - 1, true);
        c.SetMinSum(val); // allowed only before initialization in P
        c.Initialized();  // top-level: mark contract as initialized
        bool reverted;
        try c.SetMinSum(val) { reverted = false; } catch { reverted = true; }   // boundary
        assert(reverted); // once initialized, SetMinSum must always revert (P), mutant lets it through
    }
    receive() external payable {}
}
